SELECT gen_random_uuid()::text, 'formula', '$I_A \propto \frac{1}{1 - (\alpha_1 + \alpha_2)}$', 'SCR Two-Transistor Model', '$I_A = \frac{\alpha_2I_G + I_{CBO1} + I_{CBO2}}{1 - (\alpha_1 + \alpha_2)}$', '$\text{A}$', 'Why an SCR latches: as α₁ + α₂ approaches 1 the anode current runs away, limited only by the load.', '[{"symbol":"$\\alpha_1, \\alpha_2$","meaning":"common-base gains of the PNP and NPN halves","unit":null},{"symbol":"$I_G$","meaning":"gate current","unit":"$\\text{A}$"},{"symbol":"$I_{CBO1}, I_{CBO2}$","meaning":"leakage currents","unit":"$\\text{A}$"}]'::jsonb, 'Once on, removing the gate current does nothing: the SCR stays on until the current falls below the holding current.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'thyristors and scrs' AND s."active"), NULL, false, 'PENDING', now(), now()
