SELECT gen_random_uuid()::text, 'formula', '$\text{DRF} = 1 - \frac{V_s}{n_sV_{DRM}}$', 'Series and Parallel String Derating', '$\text{DRF}_{series} = 1 - \frac{V_s}{n_sV_{DRM}},\qquad \text{DRF}_{parallel} = 1 - \frac{I_T}{n_pI_{TM}}$', NULL, 'How much of the combined rating a string leaves unused to allow for unequal sharing.', '[{"symbol":"$V_s, I_T$","meaning":"string voltage and current","unit":null},{"symbol":"$n_s, n_p$","meaning":"devices in series and in parallel","unit":null},{"symbol":"$V_{DRM}, I_{TM}$","meaning":"one device''s voltage and current ratings","unit":null}]'::jsonb, 'A higher derating factor means more devices than the bare minimum, for reliability.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'thyristors and scrs' AND s."active"), NULL, true, 'PENDING', now(), now()
