SELECT gen_random_uuid()::text, 'formula', '$R = \frac{n_sV_{D,max} - V_s}{(n_s - 1)\Delta I_D}$', 'Static Voltage-Equalising Resistor', '$R = \frac{n_sV_{D,max} - V_s}{(n_s - 1)\,\Delta I_D}$', '$\Omega$', 'The largest shunt resistor across each SCR that keeps the lowest-leakage device within its rating.', '[{"symbol":"$n_s$","meaning":"SCRs in series","unit":null},{"symbol":"$V_{D,max}$","meaning":"highest voltage one device may block","unit":"$\\text{V}$"},{"symbol":"$V_s$","meaning":"string voltage","unit":"$\\text{V}$"},{"symbol":"$\\Delta I_D$","meaning":"spread in leakage current","unit":"$\\text{A}$"}]'::jsonb, 'The device with the LEAST leakage takes the most voltage; dynamic sharing needs a capacitor too.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'thyristors and scrs' AND s."active"), NULL, false, 'PENDING', now(), now()
