SELECT gen_random_uuid()::text, 'formula', '$f = \frac{1}{RC\ln\frac{1}{1 - \eta}}$', 'UJT Relaxation Oscillator', '$f = \frac{1}{RC\ln\frac{1}{1 - \eta}},\qquad V_P = \eta V_{BB} + V_D,\qquad \frac{V_{BB} - V_V}{I_V} < R < \frac{V_{BB} - V_P}{I_P}$', '$\text{Hz}$', 'A capacitor charges until the UJT fires at Vp, discharges into the gate, and repeats: a pulse train for SCR triggering.', '[{"symbol":"$\\eta$","meaning":"intrinsic stand-off ratio","unit":null},{"symbol":"$R, C$","meaning":"timing resistor and capacitor","unit":null},{"symbol":"$V_P, V_V$","meaning":"peak and valley voltages","unit":"$\\text{V}$"},{"symbol":"$I_P, I_V$","meaning":"peak and valley currents","unit":"$\\text{A}$"}]'::jsonb, 'R outside its range: too large and the UJT never fires, too small and it never turns off.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'thyristors and scrs' AND s."active"), NULL, false, 'PENDING', now(), now()
