SELECT gen_random_uuid()::text, 'formula', '$V_o = V_s\sqrt{(\pi - \alpha + \tfrac12\sin2\alpha)/\pi}$', 'AC Phase Control Output (Resistive Load)', '$V_o = V_s\sqrt{\frac{1}{\pi}\left(\pi - \alpha + \frac{\sin 2\alpha}{2}\right)},\qquad P = \frac{V_o^2}{R}$', '$\text{V}$', 'The rms output of a triac (or two antiparallel SCRs) fired at α in both half-cycles.', '[{"symbol":"$V_s$","meaning":"rms supply voltage","unit":"$\\text{V}$"},{"symbol":"$\\alpha$","meaning":"firing (delay) angle","unit":null},{"symbol":"$R$","meaning":"load resistance","unit":"$\\Omega$"}]'::jsonb, 'At α = 90° the output is 0.707 Vs and the power is half of full.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'triacs and diacs' AND s."active"), NULL, false, 'PENDING', now(), now()
