SELECT gen_random_uuid()::text, 'formula', '$\theta = -\tan^{-1}\omega RC$', 'RC Phase-Shift Firing Network', '$V_C = \frac{V_s}{\sqrt{1 + (\omega RC)^2}}\ \angle{-\tan^{-1}(\omega RC)}$', '$\text{V}$', 'The capacitor voltage lags the supply, so the diac breaks over (and fires the triac) later in each half-cycle.', '[{"symbol":"$V_s$","meaning":"supply voltage","unit":"$\\text{V}$"},{"symbol":"$R, C$","meaning":"firing network resistance and capacitance","unit":null},{"symbol":"$\\omega$","meaning":"supply angular frequency","unit":"$\\text{rad/s}$"}]'::jsonb, 'Raising R delays the firing and dims the lamp; a single RC gives at most about 90° of delay.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'triacs and diacs' AND s."active"), NULL, false, 'PENDING', now(), now()
