SELECT gen_random_uuid()::text, 'formula', '$V_{dc} = 1.35V_{LL}\cos\alpha - \frac{3\omega L_sI_d}{\pi}$', 'Commutation Overlap', '$V_{dc} = 1.35V_{LL}\cos\alpha - \frac{3\omega L_s}{\pi}I_d,\qquad \cos\alpha - \cos(\alpha + \mu) = \frac{\sqrt2\,\omega L_sI_d}{V_{LL}}$', '$\text{V}$', 'Source inductance makes current transfer between phases take an angle μ, which costs output voltage.', '[{"symbol":"$V_{LL}$","meaning":"rms line-to-line supply voltage","unit":"$\\text{V}$"},{"symbol":"$\\alpha$","meaning":"firing (delay) angle","unit":null},{"symbol":"$L_s$","meaning":"source inductance per phase","unit":"$\\text{H}$"},{"symbol":"$I_d$","meaning":"DC current","unit":"$\\text{A}$"},{"symbol":"$\\mu$","meaning":"overlap angle","unit":null}]'::jsonb, 'The drop acts like a resistance 3ωLs/π that dissipates nothing.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'controlled rectifiers' AND s."active"), 'Three-phase', false, 'PENDING', now(), now()
