SELECT gen_random_uuid()::text, 'formula', '$V_{n} = \frac{4V_{dc}}{n\pi\sqrt2} = \frac{0.9V_{dc}}{n}$', 'Square-Wave Inverter Harmonics', '$V_{n,rms} = \frac{4V_{dc}}{n\pi\sqrt2} = \frac{0.9V_{dc}}{n}\ (n \text{ odd}),\qquad V_{o,rms} = V_{dc}\quad (\text{full bridge})$', '$\text{V}$', 'A full-bridge square wave: only odd harmonics, each 1/n of the fundamental.', '[{"symbol":"$V_{dc}$","meaning":"DC supply voltage","unit":"$\\text{V}$"},{"symbol":"$n$","meaning":"harmonic order","unit":null}]'::jsonb, 'A half bridge gives half these values. The square wave''s THD is 48.3%.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'inverters' AND s."active"), NULL, false, 'PENDING', now(), now()
