SELECT gen_random_uuid()::text, 'formula', '$V_{LL1} = \frac{\sqrt6}{\pi}V_{dc} = 0.78V_{dc}$', 'Six-Step Three-Phase Inverter', '$V_{LL1,rms} = \frac{\sqrt6}{\pi}V_{dc} = 0.78V_{dc},\quad V_{LL,rms} = \sqrt{\tfrac23}V_{dc} = 0.816V_{dc},\quad V_{ph,rms} = \frac{\sqrt2}{3}V_{dc} = 0.471V_{dc}$', '$\text{V}$', 'A three-phase bridge with 180° conduction: stepped phase voltages, no triplen harmonics.', '[{"symbol":"$V_{dc}$","meaning":"DC supply voltage","unit":"$\\text{V}$"}]'::jsonb, 'Harmonics left are 5, 7, 11, 13… (6k ± 1).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'inverters' AND s."active"), NULL, false, 'PENDING', now(), now()
