SELECT gen_random_uuid()::text, 'formula', '$V_{LL1} = 0.612\,m_aV_{dc}$', 'Sinusoidal PWM', '$m_a = \frac{V_{ref}}{V_{carrier}},\ m_f = \frac{f_{carrier}}{f_{ref}};\quad \hat V_{1} = m_a\frac{V_{dc}}{2}\ (\text{leg}),\quad V_{LL1,rms} = 0.612\,m_aV_{dc}$', '$\text{V}$', 'Compare a sine reference with a triangle carrier: the fundamental follows m_a, harmonics move up near m_f.', '[{"symbol":"$m_a$","meaning":"amplitude modulation index (linear up to 1)","unit":null},{"symbol":"$m_f$","meaning":"frequency modulation ratio","unit":null},{"symbol":"$V_{dc}$","meaning":"DC supply voltage","unit":"$\\text{V}$"}]'::jsonb, 'Above m_a = 1 (overmodulation) the fundamental stops rising linearly and low harmonics return.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'inverters' AND s."active"), NULL, false, 'PENDING', now(), now()
