SELECT gen_random_uuid()::text, 'formula', '$V_o = DV_s,\ \Delta I_L = \frac{V_sD(1 - D)}{Lf}$', 'Buck (Step-Down) Chopper', '$V_o = DV_s,\qquad \Delta I_L = \frac{V_sD(1 - D)}{Lf}$', '$\text{V}$', 'Output is the input chopped to its average; the inductor smooths the current.', '[{"symbol":"$V_s$","meaning":"input voltage","unit":"$\\text{V}$"},{"symbol":"$D$","meaning":"duty ratio, on-time over period","unit":null},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"},{"symbol":"$f$","meaning":"switching frequency","unit":"$\\text{Hz}$"}]'::jsonb, 'Inductor ripple is largest at D = 0.5.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'choppers' AND s."active"), NULL, false, 'PENDING', now(), now()
