SELECT gen_random_uuid()::text, 'formula', '$\omega = \frac{V_{dc}(\alpha) - I_aR_a}{K\phi}$', 'Converter-Fed DC Motor Speed', '$\omega = \frac{V_{dc}(\alpha) - I_aR_a}{K\phi},\qquad V_{dc}(\alpha) = \frac{2V_m}{\pi}\cos\alpha\ \text{or}\ 1.35V_{LL}\cos\alpha$', '$\text{rad/s}$', 'Phase control of the armature voltage sets the speed of a separately excited DC motor.', '[{"symbol":"$V_{dc}(\\alpha)$","meaning":"converter output voltage","unit":"$\\text{V}$"},{"symbol":"$I_a, R_a$","meaning":"armature current and resistance","unit":null},{"symbol":"$K\\phi$","meaning":"motor constant times flux","unit":"$\\text{V·s/rad}$"}]'::jsonb, 'Torque is Kφ·Ia: set by the load, not by α.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'motor drives' AND s."active"), NULL, false, 'PENDING', now(), now()
