SELECT gen_random_uuid()::text, 'formula', '$\frac{T_{max2}}{T_{max1}} = \left(\frac{f_1}{f_2}\right)^2$', 'Breakdown Torque Above Base Speed', '$T_{max} \propto \left(\frac{V}{f}\right)^2 \implies \frac{T_{max2}}{T_{max1}} = \left(\frac{f_1}{f_2}\right)^2\quad (V \text{ fixed above base speed})$', NULL, 'Above base speed the inverter can''t raise the voltage, so the flux and breakdown torque fall.', '[{"symbol":"$f_1, f_2$","meaning":"base and new supply frequency","unit":"$\\text{Hz}$"},{"symbol":"$T_{max}$","meaning":"breakdown torque","unit":"$\\text{N·m}$"}]'::jsonb, 'Rated torque falls as 1/f (constant power); breakdown torque falls faster, as 1/f².', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'motor drives' AND s."active"), NULL, true, 'PENDING', now(), now()
