SELECT gen_random_uuid()::text, 'formula', '$n = \frac{V_{dc,min}}{V_{end}}$', 'Number of Battery Cells', '$n = \frac{V_{dc,min}}{V_{end/cell}},\qquad n\,V_{float/cell} \le V_{dc,max}$', NULL, 'Enough cells to stay above the inverter''s minimum at the end of discharge, few enough not to exceed its maximum on float.', '[{"symbol":"$V_{dc,min}, V_{dc,max}$","meaning":"inverter''s DC input window","unit":"$\\text{V}$"},{"symbol":"$V_{end/cell}$","meaning":"end voltage per cell (1.75 V lead-acid)","unit":"$\\text{V}$"},{"symbol":"$V_{float/cell}$","meaning":"float voltage per cell (about 2.25 V)","unit":"$\\text{V}$"}]'::jsonb, 'Lead-acid: 2 V nominal, about 2.25 V float, 1.75 V end per cell.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'ups' AND s."active"), NULL, true, 'PENDING', now(), now()
