SELECT gen_random_uuid()::text, 'formula', '$V_H = \frac{IB}{nqt}$', 'Hall Effect Voltage', '$V_H = \frac{IB}{nqt} = R_H\frac{IB}{t},\qquad R_H = \frac{1}{nq}$', '$\text{V}$', 'A magnetic field pushes moving carriers to one side, giving a voltage across the plate.', '[{"symbol":"$I$","meaning":"current through the plate","unit":"$\\text{A}$"},{"symbol":"$B$","meaning":"flux density","unit":"$\\text{T}$"},{"symbol":"$n$","meaning":"carrier density","unit":"$\\text{m}^{-3}$"},{"symbol":"$t$","meaning":"plate thickness","unit":"$\\text{m}$"}]'::jsonb, 'Semiconductors (low n) give far larger Hall voltages than metals: used for current and position sensing.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'sensors' AND s."active"), NULL, false, 'PENDING', now(), now()
