SELECT gen_random_uuid()::text, 'formula', '$Q = dF,\ V = \frac{dF}{C}$', 'Piezoelectric Sensor', '$Q = dF,\qquad V = \frac{Q}{C} = \frac{gFt}{A},\qquad g = \frac{d}{\varepsilon_0\varepsilon_r}$', '$\text{V}$', 'Force on a crystal produces charge: ideal for vibration, pressure and force changes.', '[{"symbol":"$d$","meaning":"charge sensitivity","unit":"$\\text{C/N}$"},{"symbol":"$F$","meaning":"force","unit":"$\\text{N}$"},{"symbol":"$t, A$","meaning":"crystal thickness and area","unit":null},{"symbol":"$g$","meaning":"voltage sensitivity","unit":"$\\text{V·m/N}$"}]'::jsonb, 'Charge leaks away through the input resistance: piezo sensors cannot measure static force.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Industrial Electronics' AND t."subject" = 'EE' AND s."normKey" = 'sensors' AND s."active"), NULL, false, 'PENDING', now(), now()
